const meta=$('Fetch + extract replies (all bots)').all();
const resps=$input.all();
function norm(t){t=String(t||'').toLowerCase();if(t.includes('opt'))return 'Opt-out';if(t.includes('posit'))return 'Positive';if(t.includes('negat'))return 'Negative';return 'Neutral';}
const replies=[];
for(let i=0;i<meta.length;i++){let txt='';try{txt=resps[i].json.content[0].text;}catch(e){txt='';}replies.push({location_id:meta[i].json.location_id,contactId:meta[i].json.contactId,email:meta[i].json.email,sentiment:norm(txt),ts:meta[i].json.ts});}
return [{json:{replies}}];

const BOTS=[{loc:'htgHvVfBZ1WH3UpQoxaa',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'PXyGarBjp2lwuVBdA81P',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'1lP8kn6tPERda0fT4zVT',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'XAF0RGBybE8RoesJhSiz',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'96LqPx5WmcloFPZZe1hy',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'kuO6oj3iKtz5PQUu4WZ0',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'NsDKFz05b8v0P86nTc2o',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'sEjuiURUKweddSIqjcjT',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'qT3OTNWfVeq0tNWklhMK',tok:'pit-REDACTED_PER_LOCATION_TOKEN'}];
const oppsWon={};
for(const b of BOTS){
  oppsWon[b.loc]=[];
  let url='https://services.leadconnectorhq.com/opportunities/search?location_id='+b.loc+'&limit=100';
  let pages=0;
  while(url&&pages<30){
