const replies=$('Collect classified').first().json.replies||[];
const oppsWon=$('Fetch opportunities (all bots)').first().json.oppsWon||{};
const sf=$input.all().map(i=>i.json).filter(x=>x&&x.Email);
const fundedByEmail={};
for(const row of sf){const email=String(row.Email).toLowerCase();const opp=row.ConvertedOpportunity||{};if(opp.StageName==='Funded')fundedByEmail[email]=(fundedByEmail[email]||0)+Number(opp.csbs__Commission_Amount__c||0);}
const byLoc={};
for(const r of replies){(byLoc[r.location_id]=byLoc[r.location_id]||[]).push(r);}
const out=[];
for(const loc of Object.keys(byLoc)){
  const rs=byLoc[loc];
  const counts={};
  for(const r of rs){const d=new Date(Number(r.ts));const ym=d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0');counts[ym+'|'+r.sentiment]=(counts[ym+'|'+r.sentiment]||0)+1;}
  const p_rows=Object.entries(counts).map(([k,v])=>{const a=k.split('|');return{payout_month:a[0],sentiment:a[1],reply_count:v};});
  const won=new Set(oppsWon[loc]||[]);
  const posReplies=rs.filter(r=>r.sentiment==='Positive');
  const posContacts=new Set(posReplies.map(r=>r.contactId).filter(Boolean));
  let advanced=0;for(const c of posContacts)if(won.has(c))advanced++;
  const posEmails=[...new Set(posReplies.map(r=>(r.email||'').toLowerCase()).filter(Boolean))];
  let positive_funded=0,funded_commission=0;
  for(const e of posEmails)if(fundedByEmail[e]!==undefined){positive_funded++;funded_commission+=fundedByEmail[e];}
  funded_commission=Math.round(funded_commission*100)/100;
  out.push({json:{p_location:loc,p_rows,p_positive_replies:posContacts.size,p_positive_advanced:advanced,p_positive_funded:positive_funded,p_funded_commission:funded_commission}});
}
return out;
